      ($t$hustle-and-muscle$t$, 0, true, $t$Hustle & Muscle$t$, $t$Gym website$t$, $t$Fitness · Web design & build$t$, array[$t$web$t$, $t$brand$t$]::text[], array[$t$fitness$t$]::text[], 2026, $t$May–Nov 2026$t$, $t$Designer & builder · passion project$t$, $t$Designer and developer, passion project, building with Claude as an AI pair programmer$t$, $t$Web$t$, $t$live$t$, $t$https://hustle-and-muscle.vercel.app/$t$, $t$/docs/hustle-and-muscle-documentation.pdf$t$, $t$/docs/hustle-and-muscle-design-system.pdf$t$, $j$[{"label":"Homepage","src":"/projects/hustle-and-muscle/home.webp"},{"label":"Class cards","src":"/projects/hustle-and-muscle/classes.webp"},{"label":"Coach J.R. chat","src":"/projects/hustle-and-muscle/coach-jr.webp"}]$j$::jsonb, $j$[{"label":"Designed in May, built in November","value":"Hi-fi Figma designs first, then the build, in ten commits over two days."},{"label":"3 designs, 29 pages","value":"The shop, cart, classes and coach profiles were built from the design system alone."},{"label":"Coach J.R.","value":"A guided chat bot in English and Filipino, with a witty Bisaya voice."}]$j$::jsonb, $j$[{"value":"29","label":"pages from 3 Figma designs"},{"value":"2 days","label":"from Figma to a deployed site"},{"value":"2","label":"languages Coach J.R. speaks"}]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, May 2026","body":"A good friend turned out to own a gym, so I designed Hustle & Muscle a website in hi-fi Figma: the homepage, contact and coaches pages. Black ground, huge type, one hot orange and cut corners."},{"stage":"challenge","label":"Context & challenge","date":"November 2026","body":"Six months later I wanted those designs to be a real site. Three designed pages had to become every page a member would reach for (plans, classes, coaches, a shop, policies) without a backend and without the look falling apart."},{"stage":"approach","label":"Approach","date":"Along the way","body":"Tokens first: every color, size and corner from Figma became a named Tailwind token, so the 26 undesigned pages could match the three designed ones. Then one cart for everything, forms that open with the topic filled in, and Coach J.R., a guided bot instead of an AI one, because a gym bot should never make up a price."},{"stage":"outcome","label":"Outcome","date":"November 2026","body":"It's deployed on Vercel. Kirsten Corpuz, the gym's co-founder, has seen it, called it great, and plans to take it live after the third branch opens."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"Building with Claude turned six-month-old Figma frames into a working site in two days. The design calls stayed mine. Deciding what not to build (no AI, no backend, no payments yet) kept it honest."}]$j$::jsonb),
      ($t$resonate$t$, 1, true, $t$Resonate$t$, $t$Coaching & voiceover platform$t$, $t$Personal brand platform · Web design$t$, array[$t$web$t$, $t$brand$t$]::text[], array[$t$coaching$t$, $t$voice$t$]::text[], 2026, $t$Mar–Jul 2026$t$, $t$Designer & builder · solo$t$, $t$Product Designer & Builder (freelance), solo, working directly with the client$t$, $t$Web$t$, $t$live$t$, $t$https://erwin-natividad-2026.vercel.app/$t$, null, null, $j$[{"label":"Home"},{"label":"Discovery-call flow"},{"label":"Admin dashboard"}]$j$::jsonb, $j$[{"label":"Solo, problem to launch","value":"Designed and built the whole platform, working directly with Erwin."},{"label":"March 2026 – July 2026","value":"About five months from first call to live site."},{"label":"Booking-first","value":"Discovery calls, waitlist logic, a podcast platform and an admin dashboard."}]$j$::jsonb, $j$[]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, March 2026","body":"Erwin is a voice coach and voiceover artist. He didn’t need more talent. He needed a place that made the talent findable. So I’m building him a booking-first home where coaching leads and the voiceover work backs it up."},{"stage":"challenge","label":"Context & challenge","date":"March 2026","body":"His work is scattered across channels, and nothing says “coach” to someone deciding whether to book him. Even when people find him, there’s no path from interested to booked."},{"stage":"approach","label":"Approach","date":"Along the way","body":"One hierarchy of intent: coaching first, voiceover as proof, booking always one step away. Then a discovery-call flow with waitlist logic, a podcast platform, and a dashboard so Erwin can update bookings, podcasts, portfolio and blog without calling a developer."},{"stage":"outcome","label":"Outcome","date":"July 2026","body":"It’s live. Erwin told me it felt personal, built from a Pinterest board and a vague idea, and that it loads fast."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"Talent was never the problem. Findability was. That’s the lesson I’m keeping."}]$j$::jsonb),
      ($t$sailswipe$t$, 2, true, $t$SailSwipe$t$, $t$Maritime marketplace$t$, $t$Maritime marketplace · Mobile app design$t$, array[$t$mobile$t$, $t$market$t$, $t$saas$t$]::text[], array[$t$saas$t$, $t$maritime$t$, $t$marketplace$t$]::text[], 2025, $t$Jan–Apr 2025$t$, $t$Product designer · sole designer$t$, $t$Product Designer, sole designer, working directly with the founder$t$, $t$iOS + Android$t$, $t$handed-off$t$, null, null, null, $j$[{"label":"Swipe browsing"},{"label":"Owner path"},{"label":"Crew path"}]$j$::jsonb, $j$[{"label":"Sole designer","value":"Worked straight with the founder on product and business. No developer embedded during design."},{"label":"January 2025 – April 2025","value":"Four months, mobile-first for iOS and Android."},{"label":"Three paths","value":"Separate journeys for yacht owners, crew members and travelers."}]$j$::jsonb, $j$[]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, January 2025","body":"New brief: a maritime marketplace for yacht owners, crew and travelers. And they want it to swipe like a dating app."},{"stage":"challenge","label":"Context & challenge","date":"January 2025","body":"The current web platform is cluttered: blogs, port data and listings stacked with no structure. People stay because finding a port or reaching crew still happens there, but the JavaScript-heavy build slows exactly those moments."},{"stage":"approach","label":"Approach","date":"Along the way","body":"I questioned the swipe. I kept the gesture but changed what it means: not accept or reject, just continuous browsing where nothing is lost by looking twice. Then I split owners, crew and travelers into their own paths."},{"stage":"outcome","label":"Outcome","date":"April 2025","body":"Handed off as structured, developer-ready Figma files, organized for async handoff."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"[Your reflection on SailSwipe goes here.]"}]$j$::jsonb),
      ($t$boses-filipina$t$, 3, true, $t$Boses Filipina$t$, $t$Voiceover portfolio platform$t$, $t$Creative portfolio · Web design$t$, array[$t$web$t$, $t$portfolio$t$, $t$brand$t$]::text[], array[$t$voice$t$, $t$creative$t$]::text[], 2025, $t$Jun 2025–Feb 2026$t$, $t$Designer & builder · pro bono$t$, $t$Product Designer & Builder (pro bono), solo, working directly with the client$t$, $t$Web$t$, $t$live$t$, $t$https://www.lovelineloverez.com$t$, null, null, $j$[{"label":"Featured demos"},{"label":"Inline previews"},{"label":"Direct contact"}]$j$::jsonb, $j$[{"label":"Audio-first","value":"Agencies hear the work, get her specialization and contact her directly."},{"label":"June 2025 – February 2026","value":"Eight months of design and build."},{"label":"Prompt-based workflow","value":"A real test of how far a prompt-based workflow can carry a real product."}]$j$::jsonb, $j$[]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, June 2025","body":"A voiceover artist asked me for a portfolio. I’m building her an audio-first home instead, where agencies and clients can hear her work, understand her specialization and reach her directly."},{"stage":"challenge","label":"Context & challenge","date":"June 2025","body":"Marketplaces like Fiverr and Voices.com take away control over presentation, branding and discovery. In a marketplace every artist looks roughly the same."},{"stage":"approach","label":"Approach","date":"Along the way","body":"Clients scan titles, play a few seconds and decide almost immediately. So featured demos sit above the fold, previews play right from the cards, and nothing stands between landing and listening."},{"stage":"outcome","label":"Outcome","date":"February 2026","body":"Shipped and live. Conversion tooling is saved for a later phase, on purpose."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"[Your reflection on Boses Filipina goes here.]"}]$j$::jsonb),
      ($t$cishifts$t$, 4, true, $t$CISHIFTS$t$, $t$Healthcare workforce platform$t$, $t$Healthcare SaaS · UI/UX design$t$, array[$t$saas$t$, $t$health$t$, $t$mobile$t$]::text[], array[$t$saas$t$, $t$healthcare$t$]::text[], 2023, $t$Mar 2023–Dec 2024$t$, $t$Product designer · team of up to 9$t$, $t$Product Designer, from sole designer to one of two designers on the team$t$, $t$Mobile app + web dashboard$t$, $t$not-shipped$t$, null, null, null, $j$[{"label":"Nurse app"},{"label":"Clinic dashboard"},{"label":"Shift feed"}]$j$::jsonb, $j$[{"label":"Two platforms, one system","value":"A mobile app for nurses and a web dashboard for clinics and agencies."},{"label":"22 months","value":"March 2023 to December 2024."},{"label":"The team doubled","value":"Phase 1: me, 3 developers, 1 PM. Phase 2: 2 designers, 6 developers, 1 PM."}]$j$::jsonb, $j$[{"value":"6 days","label":"cut from nurse onboarding"},{"value":"5","label":"disconnected tools replaced"},{"value":"2","label":"platforms unified into one system"}]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, March 2023","body":"Today I started on CISHIFTS: a mobile app for nurses and a web dashboard for clinics and agencies, meant to replace a pile of disconnected tools."},{"stage":"challenge","label":"Context & challenge","date":"Early days","body":"Filling one shift means jumping between five systems: WellSky, Salesforce, Google Workspace, Monday and ADP. Open shifts sit for days, and last-minute cancellations are slow to fill."},{"stage":"approach","label":"Approach","date":"Along the way","body":"Two platforms, one synchronized system. When a clinic posts a shift, it lands in a nurse’s feed. When someone cancels, nearby nurses get notified. Halfway through, the team doubled and I stopped being the only designer."},{"stage":"outcome","label":"Outcome","date":"December 2024","body":"It never shipped. But the system is complete and fully documented, end to end."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"This project taught me what it means to design something that genuinely matters. The complete, documented system is the part I’d defend."}]$j$::jsonb);
