    values
      ($t$site$t$, $t$profile$t$, 0, $t$Profile$t$, $j${"name":"Chris Paynaganan","role":"Product & Experience Designer","location":"Lipa City, Batangas, Philippines","email":"mark.payns@gmail.com","replyTime":"Replies personally, usually within a day or two","tagline":"I build websites that make you money.","calendlyUrl":"https://calendly.com/uxbychrisph/the-virtual-coffee","resumeUrl":"https://buxyunximvrtzhmwvdnp.supabase.co/storage/v1/object/public/site-assets/about-hero-resume-354a595e-a5f8-463a-8ccf-ffbaeeb7ca37.pdf","heroLine":"Product & Experience Designer, based in Batangas.","hostTeaser":"I started as a graphic artist, joined the military for steady income, and found my way back to design through a developer bootcamp. These days I design and build, mostly solo.","inTheWorks":"In the works: AI automation, like custom chatbots for client sites. Not offered yet.","enterprise":{"label":"Chris Enterprise","url":"https://www.ohyvi.com"}}$j$::jsonb),
      ($t$site$t$, $t$story$t$, 0, $t$Story, part 1$t$, $j${"body":"Dear diary. I started out as a graphic artist, then joined the military for steady income. When I’d saved enough to go back to design, the pandemic hit, so I took call center shifts, taught ESL and did virtual assistant work. A developer bootcamp pulled me back in, and that’s where I fell for interface design and for being genuinely useful to people. My first design job came with early work I still think of as imperfect but meaningful."}$j$::jsonb),
      ($t$site$t$, $t$story$t$, 1, $t$Story, part 2$t$, $j${"body":"I began on a team handling documentation, user research and design. Now I lead solo projects across healthcare, fitness, accounting and, lately, voice acting. I even see a little military discipline in how I run UX research."}$j$::jsonb),
      ($t$site$t$, $t$karinderya$t$, 0, $t$What a karinderya taught me$t$, $j${"body":"I love food with a story behind it, and I’m drawn to karinderyas. They serve it fresh, they know their regulars, and they adapt to the street they’re on. Design works the same way: two products can solve the same problem and still look completely different, because they’re shaped by who they serve."}$j$::jsonb),
