      ($t$site$t$, $t$house-rules$t$, 0, $t$Quick, clear replies$t$, $j${"body":"Fast but thoughtful, always with a next step. No long silences."}$j$::jsonb),
      ($t$site$t$, $t$house-rules$t$, 1, $t$Honest scope$t$, $j${"body":"Minor feedback is not a revision, and I don’t pad scope."}$j$::jsonb),
      ($t$site$t$, $t$house-rules$t$, 2, $t$Real people over AI guesses$t$, $j${"body":"I talk to people in the industry, and re-validate research for every client."}$j$::jsonb),
      ($t$site$t$, $t$house-rules$t$, 3, $t$Timelines from deliverables$t$, $j${"body":"Rushing costs more and can cost quality. I’ll tell you up front."}$j$::jsonb),
