      ($t$business$t$, $t$addons$t$, 7, $t$Monthly maintenance$t$, $j${"usd":"$50/mo","php":"₱3,150/mo","description":"Updates, backups and small fixes after launch"}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 0, $t$Reach out$t$, $j${"body":"Instagram, email or the form below."}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 1, $t$Intake form$t$, $j${"body":"An instant email with the form and a call scheduler."}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 2, $t$Discovery call$t$, $j${"body":"Your needs, goals and where things stand."}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 3, $t$Quotation$t$, $j${"body":"For the bundle and scope we agree on."}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 4, $t$Agreement & invoice$t$, $j${"body":"Work starts once payment is in."}$j$::jsonb),
      ($t$business$t$, $t$process$t$, 5, $t$Delivery & support$t$, $j${"body":"Support by tier, then final files are yours."}$j$::jsonb),
      ($t$business$t$, $t$faq$t$, 0, $t$What if I need more revisions than my tier includes?$t$, $j${"a":"Extra rounds are a flat fee per round, and I’ll flag it before any work on them starts."}$j$::jsonb),
      ($t$business$t$, $t$faq$t$, 1, $t$Can I switch bundles mid-project?$t$, $j${"a":"Usually, yes, especially early on. Moving up or down a tier adjusts scope and price. It gets harder once development starts, so raise it early."}$j$::jsonb),
      ($t$business$t$, $t$faq$t$, 2, $t$What happens after my support window ends?$t$, $j${"a":"You keep the files, the CRM and the documentation. Later issues can be one-off fixes, or you can add monthly maintenance."}$j$::jsonb),
      ($t$business$t$, $t$faq$t$, 3, $t$Do I need to know which bundle I want before reaching out?$t$, $j${"a":"No. Most people start with a rough idea, and we settle the right tier together once the project is clearer."}$j$::jsonb),
      ($t$business$t$, $t$faq$t$, 4, $t$Is the “valued at” price real?$t$, $j${"a":"Yes. Each item is priced at what it would cost on its own, so the savings reflect actual figures."}$j$::jsonb);
